import sympy as sp

def solve_pentagon():
    c_sym = sp.symbols('c', integer=True)
    valid_c = []

    for case in ['case1', 'case2']:
        if case == 'case1':
            d_expr = c_sym - 20
        else:
            d_expr = c_sym - 8

        x = [0, 0, 14, 20, 20]
        y = [0, c_sym, c_sym - 14, d_expr, 0]

        shoelace = 0
        n = len(x)
        for i in range(n):
            x_i = x[i]
            y_i = y[i]
            x_next = x[(i + 1) % n]
            y_next = y[(i + 1) % n]
            shoelace += x_i * y_next - y_i * x_next

        area = sp.Rational(1, 2) * sp.Abs(shoelace)

        for c_val in range(1, 2026):
            if case == 'case1':
                d_val = c_val - 20
            else:
                d_val = c_val - 8

            if c_val <= 14:
                continue
            if d_val <= 0:
                continue
            if d_val >= c_val:
                continue

            curr_area = area.subs(c_sym, c_val)
            if curr_area % 16 == 0:
                valid_c.append(c_val)

    ans = len(set(valid_c))
    print(f"ANSWER: {ans}")

solve_pentagon()
