import numpy as np

def solve():
    N = 8
    # Snake filling of the grid
    grid = np.zeros((N, N), dtype=int)
    val = 1
    for i in range(N):
        if i % 2 == 0:
            for j in range(N):
                grid[i, j] = val
                val += 1
        else:
            for j in range(N-1, -1, -1):
                grid[i, j] = val
                val += 1

    M = 0
    for i in range(N):
        for j in range(N):
            if j + 1 < N:
                M += abs(grid[i, j+1] - grid[i, j])
            if i + 1 < N:
                M += abs(grid[i+1, j] - grid[i, j])

    ans = M % 1000
    print(f"ANSWER: {ans}")

if __name__ == "__main__":
    solve()
