import sympy

def solve():
    valid_integers = set()
    # Since a and b are distinct positive integers, we can loop over possible values.
    # We want a + b + ab <= 100.
    # Note: a + b + ab = (a + 1)(b + 1) - 1.
    # So (a + 1)(b + 1) <= 101.

    max_val = 100
    for a in range(1, max_val + 1):
        for b in range(1, max_val + 1):
            if a != b:
                val = a + b + a * b
                if val <= max_val:
                    valid_integers.add(val)

    ans = len(valid_integers)
    print(f"ANSWER: {sympy.latex(ans)}")

if __name__ == '__main__':
    solve()
